  if (!existingReview) {
    return null;
  }

  if (!acceptedHashes.has(existingReview.request_payload_sha256)) {
    throw new ReviewIdempotencyConflictError(idempotencyKey);
  }

  return toReviewRunResponse(existingReview);
}

