  if (Array.isArray(warnings) && warnings.length > 0) {
    response.warnings = warnings;
  }
  if (record.error_code && record.error_message) {
    response.error = {
      code: record.error_code,
      message: record.error_message,
      details: errorDetails,
    };
  }

  return response;
}

