       ORDER BY seq ASC
       LIMIT ?`
    )
    .bind(workspaceId, taskId, fromExclusive, limit)
    .all<WorkspaceTaskEventRecord>();

  return result.results.map((row) => {
    let payload: unknown;
    try {
