  repo: string,
  branch: string
): Promise<number> {
  const normalizedRepo = repo.trim();
  const normalizedBranch = branch.trim();
  if (!normalizedRepo || !normalizedBranch) {
    return 0;
  }

  const row = await db
    .prepare(
      `SELECT
         COALESCE(MAX(
           CASE
             WHEN instr(rf.id, '_F-') > 0
               THEN CAST(substr(rf.id, instr(rf.id, '_F-') + 3) AS INTEGER)
             ELSE 0
           END
         ), 0) AS max_seq,
         COUNT(*) AS total_count
       FROM review_findings rf
       JOIN review_runs rr ON rr.id = rf.review_id
       WHERE rr.repo = ? AND rr.branch = ?`
    )
    .bind(normalizedRepo, normalizedBranch)
    .first<{ max_seq: number | null; total_count: number | null }>();

  const maxSeq = typeof row?.max_seq === 'number' && Number.isFinite(row.max_seq) ? row.max_seq : 0;
  const totalCount = typeof row?.total_count === 'number' && Number.isFinite(row.total_count) ? row.total_count : 0;
  return Math.max(0, Math.floor(Math.max(maxSeq, totalCount)));
}

