export async function claimWorkspaceTaskForExecution(
  db: D1Database,
  workspaceId: string,
  taskId: string
): Promise<boolean> {
  const now = new Date().toISOString();
  const result = await db
    .prepare(
      `UPDATE workspace_tasks
       SET status = 'running',
