export async function getWorkspaceDeploymentRequestPayload(
  db: D1Database,
  deploymentId: string
): Promise<Record<string, unknown> | null> {
  const record = await db
    .prepare('SELECT request_payload_json FROM workspace_deployments WHERE id = ?')
    .bind(deploymentId)
