       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT(file_path, repo) DO UPDATE SET
         branch = excluded.branch,
         cochange_json = excluded.cochange_json,
         lookback_sessions = excluded.lookback_sessions,
         last_updated = excluded.last_updated`
    )
    .bind(
