          return {
            bind() {
              return {
                async first<T>() {
                  return null as T;
                },
              };
            },
          };
        }

        if (/INSERT INTO review_runs/i.test(sql)) {
          return {
            bind(...values: unknown[]) {
              return {
                async first<T>() {
                  state.reviewExists = true;
                  try {
                    state.createdRequestPayload = JSON.parse(String(values[6])) as Record<string, unknown>;
                  } catch {
                    state.createdRequestPayload = null;
