    const response = await handleCreateReview(request, env as never, ctx, {
      accountId: 'self-hosted',
      isAdmin: true,
      isAuthenticated: false,
      isHostedMode: false,
    });
    assert.equal(response.status, 202);
    assert.equal(state.queueSendCount, 1);
