  reviewErrorCode?: string | null;
  reviewAttemptCount?: number;
  existingRequestPayloadSha256?: string;
  workerReviewGithubToken?: string;
  workspaceAccountId?: string | null;
  storedReviewRequestPayload?: Record<string, unknown>;
