  };

  const env = {
    REVIEW_CONTEXT_GITHUB_TOKEN: options?.workerReviewGithubToken ?? 'REDACTED',
    REVIEWS_QUEUE: {
      async send(message: unknown) {
        state.queueSendCount += 1;
        state.queuedMessages.push((message as Record<string, unknown>) ?? {});
      },
    },
    ReviewRunner: {
      idFromName(name: string) {
        return `do-${name}`;
      },
      get() {
