                    finished_at: null,
                    report_json: state.reportJson,
                    markdown_summary: state.markdownSummary,
                    error_code: state.errorCode,
                    error_message: null,
                    created_at: '2026-03-11T00:00:00.000Z',
                    updated_at: state.updatedAt,
                  } as T;
                },
              };
            },
          };
        }

