        }

        if (/SELECT account_id FROM workspaces WHERE id = \?/i.test(sql)) {
          return {
            bind() {
              return {
                async first<T>() {
                  return {
                    account_id:
                      options && 'workspaceAccountId' in options ? (options.workspaceAccountId ?? null) : 'acct_123',
