      values.push(additionalFields.baseline_ready);
    }
    if (additionalFields.deleted_at !== undefined) {
      updates.push('deleted_at = ?');
      values.push(additionalFields.deleted_at);
    }
    if (additionalFields.error_code !== undefined) {
