               OR julianday(candidate.created_at) > julianday(current.created_at)
               OR (
                 julianday(candidate.created_at) = julianday(current.created_at)
                 AND (current.id IS NULL OR candidate.rowid >= current.rowid)
               )
             )
         )`
    )
    .bind(...values)
    .run();
}

