  const env = {
    DB: {
      prepare(sql: string) {
        if (/UPDATE review_runs\s+SET status = 'running'/i.test(sql)) {
          return {
            bind() {
              return {
                async run() {
                  if (state.status !== 'queued') {
                    return { success: true, meta: { changes: 0 } };
