            bind() {
              return {
                async first<T>() {
                  return { request_payload_json: JSON.stringify(payload) } as T;
                },
              };
            },
          };
        }

        if (/SELECT \* FROM workspaces WHERE id = \?/i.test(sql)) {
          return {
            bind() {
              return {
                async first<T>() {
                  return (options?.workspaceRecord === undefined
                    ? {
